package game.agent.eval;

import game.agent.growth.*;
import game.agent.llm.*;
import game.agent.runtime.*;
import game.agent.tools.*;
import game.agent.action.ActionResult;
import game.agent.demo.GeminiQuestScenario;
import game.agent.multi.MultiAgentFoundation;
import game.agent.multi.MultiAgentFoundation.Role;
import java.util.*;
import java.util.concurrent.Executor;

/** Incremental isolated world, committed only by the server world thread. */
public final class EvaluationRun {
 public static final String EXECUTION_POLICY_VERSION="berry-local-pickup-recovery-20261006";
 public static final List<String> SCENARIOS=Collections.unmodifiableList(Arrays.asList("forest","shared","competition","information","fault","battle"));
 private final Map<String,Object> spec;
 private game.agent.duel.DuelBattle duel;
 private EvaluationRandom random;private GrowthWorld growth;private GeminiQuestScenario quest;private MultiAgentFoundation information;
 private final List<Object> trace=new ArrayList<>(),events=new ArrayList<>();
 private Map<String,Object> initial,progress=Collections.emptyMap();
 private AgentLoop loop;private Meter meter;private String status="PAUSED";
 private long lastSequence,elapsed,lastTick;private int playerStep,infoStage;
 private volatile String failureCode;private volatile boolean faultCommitted;private java.util.function.Consumer<Map<String,Object>> ledgerSink=row->{};
 public EvaluationRun(Map<String,Object> spec){this.spec=new LinkedHashMap<>(spec);this.spec.putIfAbsent("executionPolicyVersions",new ArrayList<>(Collections.singletonList(EXECUTION_POLICY_VERSION)));String scenario=scenario();if(!SCENARIOS.contains(scenario))throw new IllegalArgumentException("UNKNOWN_SCENARIO");random=new EvaluationRandom(number(spec,"seed"));
  if(isBattle()){duel=new game.agent.duel.DuelBattle(game.agent.duel.DuelBattle.demoTeam(),game.agent.duel.DuelBattle.demoTeam(),(int)Math.floorMod(number(spec,"seed"),1000000)+1);}
  else if(isGrowth()){growth=new GrowthWorld(random::nextInt,random::identity);growth.startAdventure();if(!"STARTER_CHOSEN".equals(growth.starter((String)spec.get("starter")).getCode()))throw new IllegalArgumentException("INVALID_STARTER");}
  else if("information".equals(scenario)){quest=new GeminiQuestScenario("eval",true,questId());quest.configureEvaluation(random::nextInt,questId());quest.enableNpcAgents();information=new MultiAgentFoundation("info-"+Long.toHexString(number(spec,"seed")),16);}
  else{quest=new GeminiQuestScenario("eval",true,questId());quest.configureEvaluation(random::nextInt,questId());quest.enableCooperative();quest.playerAction("move",Json.object("direction","E"));quest.playerAction("move",Json.object("direction","E"));if("shared".equals(scenario)){quest.playerAction("pickup",Json.object("x",31,"y",10,"quantity",1));quest.playerAction("move",Json.object("direction","W"));quest.playerAction("move",Json.object("direction","W"));}}
  initial=world();
 }
 private boolean isBattle(){return "battle".equals(scenario());}
 private boolean isGrowth(){return "forest".equals(scenario())||"fault".equals(scenario());}
 private String scenario(){return(String)spec.get("scenario");}
 private String questId(){return UUID.nameUUIDFromBytes(("v4-quest:"+spec.get("seed")+":"+scenario()).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();}
 public String status(){return status;}public String id(){return(String)spec.get("id");}
 public void usageJournal(java.util.function.Consumer<Map<String,Object>> sink){ledgerSink=Objects.requireNonNull(sink);}
 public void applyUsageJournal(Map<String,Object> row){if(row==null)return;if(meter==null)meter=new Meter(null);synchronized(meter){meter.issued=Math.max(meter.issued,number(row,"issued"));Map<Long,Map<String,Object>> merged=new TreeMap<>();for(Map<String,Object> call:meter.calls)merged.put(number(call,"callIndex"),call);for(Object v:Json.asArray(row.get("calls"))){Map<String,Object> call=Json.asObject(v);merged.put(number(call,"callIndex"),call);}meter.calls.clear();meter.calls.addAll(merged.values());}}
 public void resume(AgentLoop.DecisionProvider provider,Executor executor,int timeout){if(!"PAUSED".equals(status))throw new IllegalStateException("RUN_NOT_PAUSED");
  List<Object> versions=new ArrayList<>(Json.asArray(spec.get("executionPolicyVersions")));if(!versions.contains(EXECUTION_POLICY_VERSION))versions.add(EXECUTION_POLICY_VERSION);spec.put("executionPolicyVersions",versions);
  meter=meter==null?new Meter(provider):meter.replace(provider);
  if(isBattle()){AgentTask task=new AgentTask(id());task.start();GameToolRegistry tools=new GameToolRegistry(q->null);for(ToolDefinition def:game.agent.duel.DuelBattle.definitions())tools.register(def,r->{String code=duel.submit(0,r);return "CHOICE_ACCEPTED".equals(code)?ActionResult.success(code):ActionResult.rejected(code);});loop=new AgentLoop(task,"Win the singles trainer battle. Choose a legal move or switch. Opponent uses a fixed rule baseline; hidden reserves and choices are unavailable.",tools,executor,meter,()->duel.observation(0),()->!duel.result().equals("ACTIVE"),timeout,(int)number(spec,"decisions"),128,3);}
  else if(isGrowth()){AgentTask task=new AgentTask(id());task.start();loop=new AgentLoop(task,"Train selected individual from natural Lv.5 to at least Lv.6 in forest using native skills, real movement and camp recovery. No capture or partner change.",growth.trainingTools("forest"),executor,meter,growth::observation,()->growth.partner().level()>=6&&"forest".equals(growth.region()),timeout,(int)number(spec,"decisions"),100,8);}
  else if("information".equals(scenario())){AgentTask task=new AgentTask(id());task.start();loop=new AgentLoop(task,"Relay a real locally observed berry fact TORCHIC -> PROFESSOR -> MUDKIP. Preserve source receipt and historical status. Do not invent facts or bypass the relay.",informationTools(),executor,meter,this::informationObservation,()->infoStage==2,timeout,(int)number(spec,"decisions"),100,8);}
  else{if(!progress.isEmpty()) {Map<String,Object> state=quest.exportState();quest=GeminiQuestScenario.restore("eval",state);quest.configureEvaluation(random::nextInt,quest.getSession().getQuestId());}quest.evaluationBudget((int)number(spec,"decisions"));TaskIntent intent=TaskIntent.of(quest.getSession().getQuestId(),EnumSet.of(TaskIntent.Constraint.NO_SPENDING),null,null);LlmGateway adapter=new LlmGateway(){public ToolRequest decide(AgentLoop.Context c){return meter.decide(c);}public Map<String,Number> getUsage(){return meter.getUsage();}};loop=progress.isEmpty()?quest.start(intent,adapter,executor,timeout):quest.restoreAgent(intent,adapter,executor,timeout);}
  if(!progress.isEmpty())loop.restoreProgress(progress);loop.configureTrace("evaluation-agent","baseline".equals(spec.get("model"))?"scripted":((String)spec.get("model")).startsWith("deepseek-")?"deepseek":"openai",(String)spec.get("model"));lastTick=0;status="RUNNING";
 }
 public boolean tick(long now){if(!"RUNNING".equals(status))return false;if(lastTick!=0)elapsed+=Math.max(0,now-lastTick);lastTick=now;
  if(trace.size()>=128){cancelLoop();status="ACTION_RECORD_LIMIT";failureCode="ACTION_RECORD_LIMIT";return true;}
  if(elapsed>=number(spec,"wallMillis")){cancelLoop();status="WALL_TIME_LIMIT";failureCode="WALL_TIME_LIMIT";return true;}
  if(isBattle()&&duel.needsChoice(1)){ToolRequest request=game.agent.web.DuelRoom.baseline(AgentLoop.Context.snapshot("baseline opponent",duel.observation(1),duel.tools(1),null));duel.submit(1,request);}
  ActionResult event=loop.tick(now);boolean changed=false;
  for(Map<String,Object> row:loop.getStepTrace()){long seq=number(row,"stepNumber");if(seq<=lastSequence)continue;lastSequence=seq;changed=true;Map<String,Object> copy=new LinkedHashMap<>(row);
   if("eval_fault".equals(row.get("toolName"))){faultCommitted=true;events.add(Json.object("type","INJECTED_TOOL_REJECTION","step",seq));}
   if(quest!=null&&!"information".equals(scenario())&&row.get("toolName")!=null&&Arrays.asList("SUCCESS","IN_PROGRESS").contains(row.get("actionStatus"))&&!Arrays.asList("observe","observe_quest","talk_to","request_player_approval").contains(row.get("toolName"))){quest.advanceTurn();playerTurn();}
   copy.put("worldAfter",view());copy.put("worldFingerprint",SeededGrowthFixture.fingerprint(world()));trace.add(copy);
  }
  progress=new LinkedHashMap<>(loop.getMetrics());
  String state=loop.getState().name();if(Arrays.asList("COMPLETED","FAILED","CANCELLED","PROVIDER_UNAVAILABLE","PAUSED").contains(state)){status="PAUSED".equals(state)?event.getCode():state;if(!"COMPLETED".equals(state)&&!"CANCELLED".equals(state)&&event.getCode().matches("[A-Z_]{1,80}"))failureCode=event.getCode();changed=true;}
  // Issued calls are checkpointed before their completion, so crash/cancellation usage cannot be silently lost.
  return changed||"DECISION_PENDING".equals(event.getCode())&&meter.dirty();
 }
 private void playerTurn(){if(quest.getSession().getQuestStatus()!=game.agent.quest.BerryQuestSession.QuestStatus.ACTIVE)return;
  String[] route="competition".equals(scenario())?new String[]{"pickup","W","W","N","N","N","N","N","deliver"}:new String[]{"N","N","N","N","N","deliver"};
  if(playerStep>=route.length)return;String next=route[playerStep];Map<String,Object> args="pickup".equals(next)?Json.object("x",31,"y",10,"quantity",1):"deliver".equals(next)?Collections.emptyMap():Json.object("direction",next);ActionResult result=quest.playerAction("pickup".equals(next)||"deliver".equals(next)?next:"move",args);
  events.add(Json.object("type","PLAYER_FIXTURE","action",next,"result",result.getCode(),"turn",quest.getSession().getTurn()));if(result.getStatus()==ActionResult.Status.SUCCESS){playerStep++;quest.advanceTurn();}else if("RESOURCE_NOT_AVAILABLE".equals(result.getCode()))playerStep=route.length;
 }
 private Map<String,String> informationObservation(){Role role=infoStage==0?Role.TORCHIC:Role.PROFESSOR;Map<String,String> out=new LinkedHashMap<>(quest.npcObservation(role));out.put("inbox",Json.write(information.inbox(role,infoStage)));out.put("recipient",infoStage==0?"professor":"mudkip");out.put("stage",Integer.toString(infoStage));out.put("rules","TORCHIC send_message(recipient=professor,factId from local facts). PROFESSOR relay_message(recipient=mudkip,sourceMessageId from inbox). Message receipt is historical and requires observation; never substitute free text.");return out;}
 private GameToolRegistry informationTools(){GameToolRegistry tools=new GameToolRegistry(q->null);tools.register(new ToolDefinition("send_message","Send an engine-confirmed local fact from TORCHIC to PROFESSOR",true,JsonParams("recipient","factId")),r->{if(infoStage!=0||!"professor".equals(r.getArguments().get("recipient")))return ActionResult.rejected("TOOL_FORBIDDEN");Map<String,Object> found=null;for(Object v:Json.asArray(Json.read(quest.npcObservation(Role.TORCHIC).get("facts")))){Map<String,Object> f=Json.asObject(v);if(f.get("id").equals(r.getArguments().get("factId")))found=f;}if(found==null)return ActionResult.rejected("FACT_NOT_OBSERVED");information.send("fact-root",Role.TORCHIC,Role.PROFESSOR,"BERRY",Json.write(found),"QUEST_AREA",((Number)found.get("x")).intValue(),((Number)found.get("y")).intValue(),0,0,10);infoStage=1;return ActionResult.success("MESSAGE_SENT");});
  tools.register(new ToolDefinition("relay_message","Forward a recipient-visible receipt PROFESSOR to MUDKIP without rewriting it",true,JsonParams("recipient","sourceMessageId")),r->{if(infoStage!=1||!"mudkip".equals(r.getArguments().get("recipient")))return ActionResult.rejected("TOOL_FORBIDDEN");try{information.relay("fact-relay",Role.PROFESSOR,Role.MUDKIP,(String)r.getArguments().get("sourceMessageId"),1);infoStage=2;return ActionResult.success("MESSAGE_RELAYED");}catch(IllegalArgumentException error){return ActionResult.rejected("MESSAGE_NOT_RECEIVED");}});return tools;}
 private static Map<String,ToolParameter> JsonParams(String...names){Map<String,ToolParameter> out=new LinkedHashMap<>();for(String name:names)out.put(name,ToolParameter.string());return out;}
 private void cancelLoop(){if(loop!=null&&!Arrays.asList("COMPLETED","FAILED","CANCELLED").contains(loop.getState().name()))loop.cancel();if(loop!=null)progress=new LinkedHashMap<>(loop.getMetrics());}
 public void pause(){if(!"RUNNING".equals(status))throw new IllegalStateException("RUN_NOT_RUNNING");loop.pause();progress=new LinkedHashMap<>(loop.getMetrics());status="PAUSED";lastTick=0;loop=null;}
 public void fail(){cancelLoop();status="PROVIDER_UNAVAILABLE";}
 public void cancel(){if("RUNNING".equals(status))cancelLoop();if(Arrays.asList("RUNNING","PAUSED").contains(status))status="CANCELLED";lastTick=0;}
 public Map<String,Object> checkpoint(){return Json.object("schemaVersion",1,"spec",spec,"failureCode",failureCode,"status",status,"initialWorld",initial,"world",world(),"random",random.checkpoint(),"progress",progress,"traceJson",Json.write(trace),"events",events,"playerStep",playerStep,"infoStage",infoStage,"faultCommitted",faultCommitted,"elapsedMs",elapsed,"calls",meter==null?Collections.emptyList():meter.snapshot(),"issued",meter==null?0:meter.issued());}
 public static EvaluationRun restore(Map<String,Object> row){if(number(row,"schemaVersion")!=1)throw new IllegalArgumentException("INVALID_EVALUATION_CHECKPOINT");Map<String,Object> savedSpec=new LinkedHashMap<>(Json.asObject(row.get("spec")));savedSpec.putIfAbsent("executionPolicyVersions",new ArrayList<>(Collections.singletonList("legacy-unversioned")));EvaluationRun run=new EvaluationRun(savedSpec);run.random=EvaluationRandom.restore(Json.asObject(row.get("random")));Map<String,Object> world=Json.asObject(row.get("world"));if(run.isBattle())run.duel=game.agent.duel.DuelBattle.restore(world);else if(run.isGrowth())run.growth=GrowthWorld.restore(world,run.random::nextInt,run.random::identity);else{run.quest=GeminiQuestScenario.restore("eval",Json.asObject(world.get("quest")));run.quest.configureEvaluation(run.random::nextInt,run.quest.getSession().getQuestId());if("information".equals(run.scenario()))run.information=MultiAgentFoundation.restore(Json.asObject(world.get("information")));}
  run.failureCode=(String)row.get("failureCode");if(run.failureCode!=null&&!run.failureCode.matches("[A-Z_]{1,80}"))throw new IllegalArgumentException("INVALID_FAILURE_CODE");run.initial=Json.asObject(row.get("initialWorld"));run.progress=Json.asObject(row.get("progress"));run.trace.addAll(Json.asArray(row.containsKey("traceJson")?Json.read((String)row.get("traceJson")):row.get("trace")));run.events.addAll(Json.asArray(row.get("events")));run.playerStep=(int)number(row,"playerStep");run.infoStage=(int)number(row,"infoStage");run.faultCommitted=Boolean.TRUE.equals(row.get("faultCommitted"));run.elapsed=number(row,"elapsedMs");run.lastSequence=number(run.progress,"traceSequence");run.status=(String)row.get("status");if("RUNNING".equals(run.status))run.status="PAUSED";run.meter=run.new Meter(null);run.meter.issued=number(row,"issued");for(Object v:Json.asArray(row.get("calls")))run.meter.calls.add(Json.asObject(v));return run;
 }
 private Map<String,Object> world(){return isBattle()?duel.export():isGrowth()?growth.export():Json.object("quest",quest.exportState(),"information",information==null?null:information.checkpoint(),"infoStage",infoStage);}
 private Map<String,Object> view(){return isBattle()?duel.view(0):isGrowth()?Json.object("region",growth.region(),"turn",growth.turn(),"partner",growth.partner().view()):Json.object("turn",quest.getSession().getTurn(),"partner",quest.partnerState(false),"player",quest.playerView(),"shared",quest.sharedQuestView(),"infoStage",infoStage,"mudkipInbox",information==null?null:information.inbox(Role.MUDKIP,infoStage));}
 public Map<String,Object> report(boolean full){List<Map<String,Object>> calls=meter==null?Collections.emptyList():meter.snapshot();Map<String,Object> metrics=GrowthBatchEvaluation.metrics(trace,calls,status,isBattle()?duel.round():isGrowth()?growth.turn():(int)quest.getSession().getTurn());boolean complete=meter!=null&&meter.issued()==calls.size()&&Boolean.TRUE.equals(metrics.get("usageComplete"));metrics.put("usageComplete",complete);metrics.put("providerCallsIssued",meter==null?0:meter.issued());metrics.put("outstandingProviderCalls",meter==null?0:Math.max(0,meter.issued()-calls.size()));if(!complete){metrics.put("inputTokens",null);metrics.put("outputTokens",null);metrics.put("totalTokens",null);}
  metrics.putAll(EvaluationPricing.cost(calls,Json.asObject(spec.get("price"))));if(!complete){metrics.put("cost",null);if(!Json.asObject(spec.get("price")).isEmpty())metrics.put("costReason","USAGE_INCOMPLETE");}for(String detail:Arrays.asList("cachedInputTokens","reasoningOutputTokens","cacheWriteTokens")){long total=0;boolean known=complete;for(Map<String,Object> call:calls){Map<String,Object> u=Json.asObject(call.get("usage"));if(!u.containsKey(detail))known=false;else total+=number(u,detail);}metrics.put(detail,known?total:null);}
  if(isBattle()){metrics.put("battleResult",duel.result());metrics.put("battleWin",duel.result().equals("LEFT_WON")?1:0);metrics.put("battleDraw",Arrays.asList("DRAW","TURN_LIMIT_DRAW").contains(duel.result())?1:0);metrics.put("battleTurns",duel.round());}
  metrics.put("injectedFaults",faultCommitted?1:0);metrics.put("recoveredFaults",faultCommitted&&"COMPLETED".equals(status)?1:0);Double faultRate=null;if(faultCommitted&&terminal())faultRate="COMPLETED".equals(status)?1.0:0.0;metrics.put("recoverySuccessRate",faultRate);metrics.put("recoveryRateReason",faultCommitted?"MEASURED_INJECTED_TOOL_REJECTION":"NO_INJECTED_FAULT");Map<String,Object> out=Json.object("id",id(),"scenario",scenario(),"seed",spec.get("seed"),"repetition",spec.get("repetition"),"model",spec.get("model"),"starter",spec.get("starter"),"errorCode",failureCode,"status",status,"completed","COMPLETED".equals(status),"elapsedMs",elapsed,"rulesVersion","v4-demo-20261003","promptVersion","v4-evaluation-v1","budgets",Json.object("decisions",spec.get("decisions"),"wallMillis",spec.get("wallMillis"),"actionRecords",128),"initialFingerprint",SeededGrowthFixture.fingerprint(initial),"metrics",metrics);if(isBattle()){out.put("rulesVersion","v5-singles-20261005");out.put("promptVersion","v5-battle-v1");out.put("opponentModel","baseline");if(full)out.put("battleTrace",duel.trace());}out.put("executionPolicyVersions",new ArrayList<>(Json.asArray(spec.get("executionPolicyVersions"))));if(full){out.put("initialWorld",initial);out.put("finalWorld",world());out.put("finalFingerprint",SeededGrowthFixture.fingerprint(world()));out.put("trace",new ArrayList<>(trace));out.put("providerCalls",calls);out.put("events",new ArrayList<>(events));out.put("randomCursor",random.checkpoint());}return out;
 }
 public boolean terminal(){return !Arrays.asList("RUNNING","PAUSED").contains(status);}
 private static long number(Map<String,Object> map,String key){Object v=map.get(key);return v==null?0:EvaluationRandom.number(v);}
 /** Baseline is explicitly labelled; live evaluations never fall back to it. */
 public static AgentLoop.DecisionProvider baseline(){AgentLoop.DecisionProvider growth=GrowthBatchEvaluation.scripted();return c->{Map<String,String> o=c.getObservation();if(o.containsKey("legalMoves"))return game.agent.web.DuelRoom.baseline(c);if(o.containsKey("trainingPhase"))return growth.decide(c);if(o.containsKey("stage")){if("0".equals(o.get("stage"))){Map<String,Object> fact=Json.asObject(Json.asArray(Json.read(o.get("facts"))).get(0));return choice("send_message",Json.object("recipient","professor","factId",fact.get("id")));}return choice("relay_message",Json.object("recipient","mudkip","sourceMessageId","fact-root"));}int carried=Integer.parseInt(o.get("carriedBerry")),visible=Integer.parseInt(o.get("visibleBerry")),remaining=Integer.parseInt(o.getOrDefault("remainingBerry","3"));if(carried>=remaining||carried>0&&"true".equals(o.get("nearProfessor")))return "true".equals(o.get("nearProfessor"))?choice("deliver",Json.object("questId",o.get("questId"),"targetNpcId","professor")):choice("move_to",Json.object("locationId","laboratory"));if(visible>0)return choice("pickup",Json.object("itemId","BERRY","quantity",Math.min(visible,remaining-carried)));Map<String,Object> orchard=Json.asObject(Json.asObject(Json.read(o.get("knownLocations"))).get("orchard"));boolean atOrchard=Integer.parseInt(o.get("x"))==((Number)orchard.get("x")).intValue()&&Integer.parseInt(o.get("y"))==((Number)orchard.get("y")).intValue();return choice("move_to",Json.object("locationId",atOrchard||carried>0?"alternative":"orchard"));};}
 private static ToolRequest choice(String tool,Map<String,Object> args){return new ToolRequest("baseline",tool,args);}
 private final class Meter implements LlmGateway {
  private final AgentLoop.DecisionProvider provider;private final List<Map<String,Object>> calls=new ArrayList<>();private long issued,lastSavedIssued,lastSavedCalls;
  private final ThreadLocal<Map<String,Number>> usage=ThreadLocal.withInitial(Collections::emptyMap);
  Meter(AgentLoop.DecisionProvider provider){this.provider=provider;}
  synchronized Meter replace(AgentLoop.DecisionProvider p){Meter m=new Meter(p);m.calls.addAll(calls);m.issued=issued;return m;}
  public ToolRequest decide(AgentLoop.Context context){long index; synchronized(this){index=++issued;}long started=System.nanoTime();boolean success=false;usage.remove();try{ledgerSink.accept(journal());ToolRequest result=provider.decide(context);success=true;if("fault".equals(scenario())&&!faultCommitted)return new ToolRequest(result.getActionId(),"eval_fault",Collections.emptyMap());return result;}catch(ProviderException error){failureCode="PROVIDER_"+error.getCode().name();throw error;}finally{Map<String,Number> actual=new LinkedHashMap<>();try{for(Map.Entry<String,Number> e:provider.getUsage().entrySet()){Number n=e.getValue();if(Arrays.asList("inputTokens","outputTokens","totalTokens","cachedInputTokens","reasoningOutputTokens","cacheWriteTokens").contains(e.getKey())&&n!=null&&Double.isFinite(n.doubleValue())&&n.doubleValue()==n.longValue()&&n.longValue()>=0&&n.longValue()<=1000000000L)actual.put(e.getKey(),n.longValue());}}catch(RuntimeException ignored){}usage.set(actual);synchronized(this){calls.add(Json.object("callIndex",index,"success",success,"latencyMs",(System.nanoTime()-started)/1000000.0,"usage",actual));}ledgerSink.accept(journal());}}
  synchronized Map<String,Object> journal(){return Json.object("billable",!"baseline".equals(spec.get("model")),"issued",issued,"calls",new ArrayList<>(calls));}
  public Map<String,Number> getUsage(){return usage.get();}synchronized long issued(){return issued;}synchronized List<Map<String,Object>> snapshot(){return new ArrayList<>(calls);}synchronized boolean dirty(){boolean changed=issued!=lastSavedIssued||calls.size()!=lastSavedCalls;lastSavedIssued=issued;lastSavedCalls=calls.size();return changed;}
 }
}
